// Package demo embeds a synthetic Claude Code session so `aiprobe demo`
// produces a full report with no API key, no network access and no real user
// data.
//
// The transcript and the tool inventory are generated by internal/demo/gen.go
// and checked in. They describe a deliberately inefficient session: tools that
// are loaded but never called, files read over and over in full, a verbose test
// command repeated four times, an idle gap past the cache TTL, a mid-session
// model switch, a rules edit that rewrites the prompt prefix, and one cache
// miss with no local explanation so the "unknown" path is exercised too.
package demo

import (
	"embed"
	"os"
	"path/filepath"
	"strings"

	"github.com/NextProbe/aiprobe/internal/adapters/claude"
	"github.com/NextProbe/aiprobe/internal/trace"
)

//go:embed testdata/demo-session.jsonl testdata/demo-mcp-tools.json
var files embed.FS

const (
	sessionFile   = "testdata/demo-session.jsonl"
	inventoryFile = "testdata/demo-mcp-tools.json"
	// SourceLabel is shown instead of a filesystem path, since the session is
	// compiled into the binary.
	SourceLabel = "embedded://demo-session.jsonl"
)

// SessionJSONL returns the raw synthetic transcript.
func SessionJSONL() ([]byte, error) { return files.ReadFile(sessionFile) }

// InventoryJSON returns the synthetic MCP tool inventory.
func InventoryJSON() ([]byte, error) { return files.ReadFile(inventoryFile) }

// Trace parses the embedded session.
func Trace() (*trace.Trace, error) {
	b, err := SessionJSONL()
	if err != nil {
		return nil, err
	}
	tr, err := claude.Parse(strings.NewReader(string(b)), SourceLabel)
	if err != nil {
		return nil, err
	}
	tr.SourcePath = SourceLabel
	tr.ProjectDir = "demo"
	return tr, nil
}

// WriteInventory materialises the tool inventory in dir and returns its path.
// The MCP analyzer reads inventories from disk, and the demo needs the same
// code path as a real run rather than a special case.
func WriteInventory(dir string) (string, error) {
	b, err := InventoryJSON()
	if err != nil {
		return "", err
	}
	path := filepath.Join(dir, "demo-mcp-tools.json")
	if err := os.WriteFile(path, b, 0o600); err != nil {
		return "", err
	}
	return path, nil
}
